const news = [
  { id: 'rate', image: 'news-rate.webp', alt: '3D-циферблат ключевой ставки', source: 'БАНК РОССИИ', date: '11 сентября 2026', time: '3 минуты', title: 'Ставку оставили на уровне 14%: кредиты пока не становятся дешёвыми', wallet: 'вклад всё ещё может быть интересным, а новый кредит лучше считать по полной переплате.', text: ['Банк России сохранил ключевую ставку 14% годовых и отметил усиление текущего ценового давления. Для семьи это не означает, что завтра изменится платёж по уже взятой ипотеке с фиксированной ставкой, но новые кредиты и рефинансирование быстро дешеветь не обязаны.', 'Мой практический вывод простой: не берите кредит только потому, что рекламная ставка выглядит ниже. Сравните полную стоимость, страховки, комиссии и дату пересмотра. Свободные деньги на короткий срок можно держать в ликвидном инструменте, но не путайте высокую ставку с гарантией на весь срок.'], url: 'https://www.cbr.ru/press/keypr/' },
  { id: 'deposits', image: 'news-deposits.webp', alt: '3D-стеклянный сейф и сбережения', source: 'БАНК РОССИИ', date: '14 сентября 2026', time: '3 минуты', title: 'Средняя максимальная ставка по вкладам топ-10 банков — 12,948%', wallet: 'ставка ещё заметная, но рекламный процент нужно проверять по сроку, сумме и условиям.', text: ['По данным Банка России, в первой декаде сентября средняя максимальная ставка по вкладам десяти крупнейших банков составила 12,948%. В начале года показатель был выше, поэтому рынок постепенно отходит от пиковых значений.', 'Это не повод срочно перекладывать все деньги в первый попавшийся вклад. Смотрите, когда банк начисляет проценты, можно ли пополнять счёт, что будет при досрочном снятии и защищены ли средства системой страхования вкладов. Вклад — это место для понятной цели и резерва, а не соревнование за красивую цифру в баннере.'], url: 'https://www.cbr.ru/statistics/avgprocstav/' },
  { id: 'family', image: 'news-family.webp', alt: '3D-семья, монета и документ', source: 'МИНТРУД', date: 'до 1 октября 2026', time: '4 минуты', title: 'Ежегодная семейная выплата: приём заявлений завершается 1 октября', wallet: 'подходящим семьям возвращают часть уплаченного НДФЛ по ставке 6% — проверьте право на выплату заранее.', text: ['На странице Минтруда указано: в 2026 году ежегодная семейная выплата рассчитывается по ставке перерасчёта НДФЛ 6%, а заявления принимаются до 1 октября. Выплата предназначена не всем подряд, поэтому сначала проверьте критерии семьи и дохода на официальном сервисе.', 'Я бы не откладывала подачу на последний вечер: соберите документы, зайдите через официальный канал и сохраните подтверждение. Деньги, которые вернулись из налогов, лучше направить в резерв, на досрочное погашение дорогого долга или на цель ребёнка — так выплата не растворится в обычных тратах.'], url: 'https://mintrud.gov.ru/' },
  { id: 'digital', image: 'news-digital-ruble.webp', alt: '3D-цифровой рубль и защищённый кошелёк', source: 'БАНК РОССИИ', date: '18 сентября 2026', time: '4 минуты', title: 'Цифровой рубль: это ещё одна форма денег, а не новый кредит', wallet: 'участие добровольное, проценты на остаток не начисляются, операции для физлиц бесплатны.', text: ['Банк России обновил разъяснения: цифровой рубль равен наличному и безналичному рублю, а все три формы денег могут существовать одновременно. Подключение добровольное, доступ идёт через приложение банка-участника.', 'Важно не ждать от цифрового кошелька доходности: на остаток проценты не начисляются, а цифровые рубли нельзя использовать как вклад. Это технологический способ платить и переводить деньги, а не замена финансовой подушке.'], url: 'https://www.cbr.ru/PSystem/dr/' },
  { id: 'weekend', image: 'news-weekend-bonds.webp', alt: '3D-календарь и облигация', source: 'MOEX', date: 'с 28 марта 2026', time: '3 минуты', title: 'Облигации на бирже торгуются по выходным: удобнее, но не безопаснее', wallet: 'купить или продать можно в субботу и воскресенье, но цена всё равно может двигаться.', text: ['Московская биржа открыла по выходным торги всеми видами облигаций с 09:50 до 19:00 по Москве. Для инвестора это удобство: не нужно ждать понедельника, если нужно провести заранее принятое действие.', 'Но длинные выходные не отменяют риск цены, ликвидности и кредитного качества эмитента. Если вы только учитесь, используйте выходной не для импульсивной покупки, а чтобы спокойно прочитать условия выпуска и понять, откуда берётся доход.'], url: 'https://www.moex.com/n98417' },
  { id: 'funds', image: 'news-money-funds.webp', alt: '3D-поток ликвидности и монеты', source: 'MOEX', date: '26 мая 2026', time: '4 минуты', title: 'В фонды денежного рынка за первые четыре месяца пришло больше 35 млрд рублей', wallet: 'инструмент стал заметным способом припарковать деньги, но это не банковский вклад и не обещание доходности.', text: ['Московская биржа сообщила, что в январе–апреле 2026 года физлица вложили более 35 млрд рублей в фонды денежного рынка. Такие фонды обычно инвестируют в короткие инструменты и стремятся следовать текущим денежным ставкам.', 'У фонда есть комиссия, рыночная цена паёв и отсутствие гарантии страхования вкладов. Перед покупкой проверьте правила фонда и срок, на который вам нужны деньги. Для резерва важнее доступность и понятность, чем лишняя десятая доля процента.'], url: 'https://www.moex.com/n100365' },
  { id: 'savings', image: 'news-long-savings.webp', alt: '3D-песочные часы, накопления и защита', source: 'ФНС РОССИИ', date: '7 июля 2025 · актуально в 2026', time: '4 минуты', title: 'Для долгосрочных сбережений можно заявить вычет с взносов до 400 000 рублей в год', wallet: 'налоговая база вычета ограничена 400 000 руб. в год — сначала проверьте договор и право на льготу.', text: ['ФНС разъясняет: взносы по договору долгосрочных сбережений могут входить в социальный налоговый вычет в совокупном размере до 400 000 рублей в год. Это не подарок от государства и не мгновенная выплата, а возврат части уже уплаченного НДФЛ при соблюдении условий.', 'Прежде чем подписывать договор, разберитесь со сроком, правилами досрочного получения денег, комиссией и государственным софинансированием. Налоговый вычет имеет смысл только тогда, когда сам продукт подходит вашей цели и горизонту.'], url: 'https://www.nalog.gov.ru/rn58/news/activities_fts/16443131/' },
  { id: 'selfban', image: 'news-self-ban.webp', alt: '3D-замок и кредитная карта', source: 'БАНК РОССИИ', date: 'обновлено 24 апреля 2026', time: '4 минуты', title: 'Самозапрет на кредиты закрывает один из путей для мошенников', wallet: 'запрет можно оформить через Госуслуги или МФЦ, но он не распространяется на ипотеку и некоторые целевые кредиты.', text: ['Банк России напоминает: самозапрет нужен, когда злоумышленники пытаются оформить кредит от имени человека. Он действует для потребительских кредитов и займов, но не для ипотеки, автокредита под залог машины и основного образовательного кредита с переводом денег учебной организации.', 'Это не замена осторожности: не называйте код из СМС и не устанавливайте приложения по просьбе звонящего. Но для человека, который не планирует новые потребительские кредиты, самозапрет — полезный дополнительный барьер.'], url: 'https://www.cbr.ru/faq/credit_h/' },
  { id: 'currency', image: 'news-digital-ruble.webp', alt: '3D-кошелёк и валютные операции', source: 'БАНК РОССИИ', date: 'обновлено 1 сентября 2026', time: '3 минуты', title: 'Операции с наличной валютой: правила продлили, детали важнее слухов', wallet: 'перед поездкой или обменом смотрите актуальные ограничения и тарифы на сайте Банка России.', text: ['Банк России продлил до 9 марта 2027 года отдельные правила для выдачи наличных долларов, евро, фунтов и иен со счетов, а также напомнил о запрете комиссии за конвертацию в эти валюты для последующей выдачи наличных при соблюдении условий.', 'Не делайте вывод по сообщению в чате или старому посту. Проверьте дату обновления, конкретную валюту и условия именно вашего банка. Для бытовой поездки важнее заранее понять доступность наличных и комиссий, чем пытаться угадать курс.'], url: 'https://cbr.ru/faq/w_fin_sector/kak_sejchas_kupit_valyutu/' },
  { id: 'fraud', image: 'news-fraud.webp', alt: '3D-смартфон и защитный щит от мошенников', source: 'БАНК РОССИИ', date: '10 августа 2026', time: '3 минуты', title: 'Банк России снова предупреждает о звонках "из банка" и "от регулятора"', wallet: 'любой звонок с просьбой перевести деньги или назвать код — повод сразу завершить разговор.', text: ['В обновлённой памятке Банк России прямо говорит: если звонящий сообщает о попытке оформить кредит и просит перевести деньги, это мошенники. Регулятор не решает такие вопросы через личные сообщения и не просит установить приложение удалённого доступа.', 'Моя привычка: положить трубку, перезвонить в банк по номеру на карте и самостоятельно проверить операции. Спешка — главный инструмент мошенника; пауза в пять минут часто стоит дороже любой комиссии, которую вам обещают отменить.'], url: 'https://www.cbr.ru/faq/information_security/' }
];

const articles = [
  { image: 'news-long-savings.webp', alt: '3D-накопления и финансовая лестница', index: '01', meta: 'Кредиты · 8 минут', tag: 'практика', title: 'Снежный ком или лавина: как закрывать кредиты без паники', intro: 'Две честные стратегии и критерий, по которому я бы выбирала между ними.', paragraphs: ['Сначала выпишите все долги: остаток, ставку, минимальный платёж и дату списания. Минимальные платежи платим по всем обязательствам, а весь дополнительный ресурс направляем в один приоритет.', 'Снежный ком — сначала самый маленький остаток. Он даёт быстрый психологический результат: один долг исчез, и деньги от его платежа переходят дальше. Лавина — сначала самая высокая ставка. Математически она обычно экономит больше процентов, но крупный долг может долго не давать ощущения прогресса.', 'Я не считаю одну стратегию правильной для всех. Если мотивация проседает, ком может оказаться эффективнее идеальной таблицы, которую вы бросите через две недели. Если дисциплина уже есть, лавина помогает сэкономить переплату. Источник с готовым сравнением — инструмент CFPB.'], links: [['Методика CFPB', 'https://files.consumerfinance.gov/f/documents/cfpb_your-money-your-goals_debt-action-plan_tool_2018-11.pdf']] },
  { image: 'news-self-ban.webp', alt: '3D-защитный замок на кредитной карте', index: '02', meta: 'Кредиты · 7 минут', tag: 'практика', title: 'Кредитка — это не дополнительные деньги', intro: 'Как вернуть карте роль инструмента и перестать закрывать одной кредиткой другую.', paragraphs: ['Кредитная карта создаёт иллюзию запаса: деньги видны в приложении, хотя часть из них уже принадлежит банку. Если вы регулярно переносите остаток и платите минимальный платёж, карта стала дорогим кредитом, а не удобным способом расчёта.', 'Начните с трёх действий: перестаньте увеличивать долг, оставьте автоплатёж минимального платежа и определите сумму сверх него. Не обнуляйте резерв ради красивого закрыла всё, но и не держите дорогой долг годами ради формальной подушки в одну тысячу рублей.', 'После погашения отключите лишние лимиты и сохраните привычку платить картой только те деньги, которые уже есть на счёте.'], links: [['Финансовая культура о кредитной истории', 'https://fincult.info/article/kreditnaya-istoriya/']] },
  { image: 'ai-system-3d.webp', alt: '3D-система финансовых инструментов', index: '03', meta: 'Инвестиции · 8 минут', tag: 'база', title: 'Что такое фондовый рынок и зачем он обычному человеку', intro: 'Акции, облигации и фонды без ощущения, что вы пришли на экзамен.', paragraphs: ['Фондовый рынок — это инфраструктура, где встречаются те, кому нужны деньги для развития, и те, кто готов временно предоставить капитал. Компания может выпустить акции, государство или бизнес — облигации, а инвестор получает право на результат и принимает риск.', 'Акция — доля в бизнесе, поэтому её цена может сильно меняться. Облигация — обязательство вернуть долг с процентом, но у неё тоже есть риск эмитента и риск изменения цены до погашения. Фонд собирает много активов в один инструмент и может упростить диверсификацию.', 'Главный вопрос новичка не что растёт, а какую цель и срок я финансирую. Если деньги нужны через несколько месяцев, рынок может оказаться слишком нервным для этой задачи.'], links: [['Учебные материалы Банка России', 'https://fincult.info/articles/']] },
  { image: 'news-deposits.webp', alt: '3D-сейф и финансовые инструменты', index: '04', meta: 'Инвестиции · 7 минут', tag: 'сравнение', title: 'Депозит или облигация: они похожи только в рекламе', intro: 'Сравниваем срок, доход, доступность денег и риск простыми словами.', paragraphs: ['Вклад — договор с банком: вы размещаете деньги на условиях, а банк платит процент. Облигация — ценная бумага: вы кредитуете эмитента, а цена может измениться до погашения. У вклада есть правила страхования, у облигации — риск эмитента и рынка.', 'Если вы знаете дату цели и не хотите наблюдать котировки, вклад может быть понятнее. Если готовы изучить выпуск, принять колебания цены и держать до погашения, облигация может занять своё место. Но доходность нельзя сравнивать без налогов, комиссий, амортизации и условий досрочного выхода.', 'Я бы начинала с ответа: могу ли я не трогать эти деньги до конца срока? Если нет, инструмент должен быть максимально ликвидным и прозрачным.'], links: [['Раздел о облигациях: Финансовая культура', 'https://fincult.info/articles/bonds/']] },
  { image: 'news-weekend-bonds.webp', alt: '3D-биржа и документ компании', index: '05', meta: 'Инвестиции · 9 минут', tag: 'анализ', title: 'Как читать компанию без диплома аналитика', intro: 'Мой порядок вопросов к отчётности, чтобы не влюбиться в красивый график.', paragraphs: ['Я начинаю с бизнеса: что компания продаёт, кому, за счёт чего растёт и что может сломать её модель. Затем смотрю выручку, прибыль, операционный денежный поток и долг не в одной точке, а в динамике нескольких периодов.', 'Отдельно проверяю качество прибыли: она пришла от основного бизнеса или от разовой переоценки? Растёт ли долг быстрее выручки? Не съедают ли проценты весь результат? Потом добавляю отраслевые риски, регулирование, дивиденды и цену самой акции.', 'Fin AI Invest в этой логике не говорит покупать. Его задача — собрать факты и показать, какие вопросы ещё нужно задать.'], links: [['Обучающие материалы Московской биржи', 'https://www.moex.com/education']] },
  { image: 'news-money-funds.webp', alt: '3D-поток ликвидности и резерв', index: '06', meta: 'Личные финансы · 6 минут', tag: 'практика', title: 'Финансовая подушка: сколько нужно именно вашей семье', intro: 'Не магическое число, а расчёт от обязательных расходов и устойчивости дохода.', paragraphs: ['Подушка нужна не для того, чтобы чувствовать себя богатой. Она нужна, чтобы поломка техники, болезнь или пауза в доходе не превращались в новый дорогой кредит. Поэтому считаем не зарплаты, а обязательные расходы: жильё, еду, лекарства, транспорт, минимальные платежи.', 'Стабильный доход и один источник заработка — разные уровни риска. Самозанятому или семье с переменным доходом нужен больший запас, чем человеку с устойчивой зарплатой и поддержкой работодателя. Начните с маленькой цели в один обязательный месяц, затем увеличивайте.', 'Резерв должен быть доступным и спокойным: не кладите его в инструмент, который может упасть в цене или закрыться на срок.'], links: [['О финансовом благополучии: CFPB', 'https://www.consumerfinance.gov/data-research/research-reports/financial-well-being-scale/']] },
  { image: 'news-family.webp', alt: '3D-абстракция семьи и монеты', index: '07', meta: 'Дети и деньги · 9 минут', tag: 'исследования', title: 'Платить ли ребёнку за оценки и домашнюю работу? Мой ответ — нет', intro: 'Почему деньги за каждую оценку превращают отношения и учёбу в сделку.', paragraphs: ['Мой ответ — нет, если речь о базовой учёбе и обычных домашних обязанностях. Когда ребёнку платят за пятёрку, он слышит: знания нужны не тебе, а чтобы получить приз. Когда платят за каждую уборку, семейный вклад превращается в прайс-лист: а сколько дадите за это?', 'Исследование Роланда Фрайера с рандомизированными экспериментами в школах показало: финансовые стимулы сами по себе не дали статистически значимого роста учебных достижений. Мета-анализ Деси, Кёстнера и Райана объясняет важную оговорку: ожидаемые материальные награды, привязанные к выполнению интересной задачи, могут ослаблять внутреннюю мотивацию. Это не означает, что нельзя хвалить или иногда дарить сюрпризы.', 'Рабочая схема: карманные деньги — регулярная сумма, не зависящая от оценок; домашние обязанности — часть жизни семьи; дополнительные задачи сверх базовых — можно оплатить. За учёбу платим временем, поддержкой, разговором и возможностью выбрать, а не купюрой за каждую строчку дневника.'], links: [['Исследование Фрайера', 'https://fryer.scholars.harvard.edu/publications/financial-incentives-and-student-achievement-evidence-randomized-trials'], ['Мета-анализ мотивации', 'https://doi.org/10.1037/0033-2909.125.6.627']] },
  { image: 'bot-mentor-3d.webp', alt: '3D-ментор и карта развития', index: '08', meta: 'Мышление · 10 минут', tag: 'исследования', title: 'Почему финансовое мышление влияет на благополучие — но не отменяет доход', intro: 'Уверенность и привычки важны, но нельзя превращать системные трудности в вину человека.', paragraphs: ['Финансовое мышление — это не мантра думай позитивно. Это способность видеть причинно-следственные связи: кредит не увеличивает доход, скидка не делает покупку бесплатной, а доходность всегда соседствует с риском. Такое мышление помогает заметить выбор раньше, чем решение становится дорогим.', 'Исследования о финансовой самоэффективности связывают ощущение я могу разобраться с более уверенными финансовыми действиями. CFPB измеряет финансовое благополучие не только цифрой дохода, а безопасностью и свободой выбора. Одновременно работа Mani и соавторов показала, что финансовая нехватка забирает когнитивный ресурс. Поэтому разговор просто думай правильно несправедлив: среда и доход действительно важны.', 'Мой практический вывод: развивайте не стыд, а три навыка — замечать автоматические траты, задавать вопросы до сделки и делать маленькие повторяемые действия. Мышление становится благополучием только вместе с доступом к доходу, защите и понятным инструментам.'], links: [['Шкала финансового благополучия CFPB', 'https://www.consumerfinance.gov/data-research/research-reports/financial-well-being-scale/'], ['Исследование Science', 'https://www.science.org/doi/abs/10.1126/science.1238041']] },
  { image: 'news-fraud.webp', alt: '3D-смартфон и защитный щит', index: '09', meta: 'Безопасность · 6 минут', tag: 'чек-лист', title: 'Как распознать финансовую пирамиду до перевода денег', intro: 'Пять вопросов к обещанию доходности, которые спасают лучше красивого логотипа.', paragraphs: ['Спросите: откуда берётся доход, кто несёт риск, можно ли проверить компанию в реестре, как вывести деньги и что произойдёт при падении рынка? Если ответ сводится к у нас закрытая стратегия, нужно зайти сегодня и пригласи двух друзей, это красные флаги.', 'Легальный сайт и презентация не равны безопасности. Проверяйте организацию на ресурсах Банка России, не передавайте коды и не устанавливайте приложения по ссылке из звонка. В инвестициях нет надёжной кнопки без риска и выше рынка.', 'Если уже перевели деньги, фиксируйте переписку, сразу звоните в банк и обращайтесь в полицию. Стыд здесь только помогает мошеннику — важна скорость.'], links: [['Памятка Банка России', 'https://www.cbr.ru/faq/pnp/']] },
  { image: 'programs-orbit-3d.webp', alt: '3D-орбита и план обучения', index: '10', meta: 'Инвестиции · 8 минут', tag: 'первый шаг', title: 'Как начать инвестировать с небольшой суммы и не перепутать старт с азартом', intro: 'Обучение, резерв и горизонт важнее суммы, с которой вы открыли брокерский счёт.', paragraphs: ['Начать можно с небольшой суммы, но начинать нужно не с покупки случайной акции. Сначала определите цель, срок и сумму, которую вы можете потерять без угрозы для обязательных расходов. Если нет резерва и есть дорогой долг, инвестиции не должны маскировать проблему.', 'Второй шаг — понять инструмент: как он приносит доход, сколько стоит, что будет при падении и как из него выйти. Третий — распределить риск, а не ставить всё на одну историю, отрасль или совет из чата.', 'Я за регулярное обучение и маленькие проверяемые действия. В инвестициях взрослая позиция — это не угадывание максимума, а готовность жить с неопределённостью и не принимать решение, которого вы не понимаете.'], links: [['Материалы Банка России для инвесторов', 'https://www.cbr.ru/finmarkets/?PrtId=investor_protection']] }
];

const renderParagraphs = (items) => items.map((item) => '<p>' + item + '</p>').join('');
const renderLinks = (items) => items.map(([label, url]) => '<a class="source-link" href="' + url + '" target="_blank" rel="noopener noreferrer">' + label + ' ↗</a>').join(' ');
const newsCard = (item) => '<article class="media-card media-card-news reveal" data-kind="news" id="news-' + item.id + '"><div class="media-card-image"><img src="' + item.image + '" alt="' + item.alt + '" loading="lazy"><span class="source-chip">' + item.source + '</span></div><div class="media-card-body"><div class="media-meta"><span>' + item.date + '</span><span>' + item.time + '</span></div><h3>' + item.title + '</h3><p class="wallet-line"><b>Для кошелька:</b> ' + item.wallet + '</p><details><summary>Читать разбор</summary>' + renderParagraphs(item.text) + '<a class="source-link" href="' + item.url + '" target="_blank" rel="noopener noreferrer">Первоисточник: ' + item.source + ' ↗</a></details></div></article>';
const articleCard = (item) => '<article class="media-card article-media-card reveal" data-kind="article" id="article-' + item.index + '"><div class="media-card-image"><img src="' + item.image + '" alt="' + item.alt + '" loading="lazy"><span class="article-index">' + item.index + '</span></div><div class="media-card-body"><div class="media-meta"><span>' + item.meta + '</span><span>' + item.tag + '</span></div><h3>' + item.title + '</h3><p>' + item.intro + '</p><details><summary>Читать статью</summary>' + renderParagraphs(item.paragraphs) + renderLinks(item.links) + '</details></div></article>';

document.getElementById('news-grid').innerHTML = news.map(newsCard).join('');
document.getElementById('articles-grid').innerHTML = articles.map(articleCard).join('');

const menuButton = document.querySelector('.menu-button');
const mobileMenu = document.querySelector('.mobile-menu');
menuButton.addEventListener('click', () => {
  const isOpen = menuButton.getAttribute('aria-expanded') === 'true';
  menuButton.setAttribute('aria-expanded', String(!isOpen));
  menuButton.setAttribute('aria-label', isOpen ? 'Открыть меню' : 'Закрыть меню');
  mobileMenu.hidden = isOpen;
  document.body.classList.toggle('menu-open', !isOpen);
});
mobileMenu.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => {
  menuButton.setAttribute('aria-expanded', 'false');
  menuButton.setAttribute('aria-label', 'Открыть меню');
  mobileMenu.hidden = true;
  document.body.classList.remove('menu-open');
}));

const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.08 });
document.querySelectorAll('.reveal').forEach((item) => revealObserver.observe(item));

document.querySelectorAll('.media-filter').forEach((button) => {
  button.addEventListener('click', () => {
    document.querySelectorAll('.media-filter').forEach((item) => item.classList.remove('is-active'));
    button.classList.add('is-active');
    const filter = button.dataset.filter;
    document.querySelectorAll('.media-card').forEach((card) => {
      card.hidden = filter !== 'all' && card.dataset.kind !== filter;
    });
    document.getElementById(filter === 'article' ? 'articles' : 'news').scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
});
